<script src="/assets/js/vendor/jquery.min.js"></script><script src="/assets/js/vendor/jquery-ui.min.js"></script><script>
(function(){var tbody=document.getElementById('reconciliation-lines'),cashId=$('#cash-account-id');if(!tbody)return;var next=tbody.querySelectorAll('[data-rec-line]').length;
function bind(row){var input=$(row).find('[data-journal-search]'),hidden=$(row).find('input[type=hidden]'),amount=$(row).find('input[name$="[statement_amount]"]'),date=$(row).find('input[type=date]'),description=$(row).find('input[name$="[description]"]');input.autocomplete({minLength:0,delay:250,source:function(req,res){$.getJSON('/admin/finance/bank_reconciliation/lookup/journal_line',{term:req.term,cash_account_id:cashId.val()}).done(res).fail(function(){res([]);});},select:function(e,item){hidden.val(item.item.id);input.val(item.item.label);amount.val(item.item.amount);date.val(item.item.date);return false;},change:function(e,item){if(!item.item)hidden.val('');}}).on('focus',function(){if(input.val()==='')input.autocomplete('search','');}).on('input',function(){hidden.val('');});$(row).find('[data-remove-line]').on('click',function(){row.remove();});}
Array.prototype.forEach.call(tbody.querySelectorAll('[data-rec-line]'),bind);
$('#cash-search').autocomplete({minLength:0,delay:250,source:function(req,res){$.getJSON('/admin/finance/bank_reconciliation/lookup/cash_account',{term:req.term}).done(res).fail(function(){res([]);});},select:function(e,item){cashId.val(item.item.id);$('#cash-search').val(item.item.label);return false;},change:function(e,item){if(!item.item)cashId.val('');}}).on('focus',function(){if($('#cash-search').val()==='')$('#cash-search').autocomplete('search','');}).on('input',function(){cashId.val('');});
document.getElementById('add-rec-line').addEventListener('click',function(){if(tbody.querySelectorAll('[data-rec-line]').length>=100)return;var i=next++,row=document.createElement('tr');row.setAttribute('data-rec-line','');row.className='border-t border-slate-100';row.innerHTML='<td class="min-w-64 p-2"><input type="hidden" name="lines['+i+'][journal_line_id]"><div class="relative"><input type="text" data-journal-search autocomplete="off" aria-autocomplete="list" required class="w-full rounded border border-slate-300 pe-8 ps-2 py-2"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true" focusable="false" class="pointer-events-none absolute end-2 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-400"><circle cx="10.8" cy="10.8" r="6.8"/><path stroke-linecap="round" d="m16 16 4.2 4.2"/></svg></div></td><td class="p-2"><input name="lines['+i+'][statement_on]" type="date" required class="rounded border border-slate-300 px-2 py-2"></td><td class="p-2"><input name="lines['+i+'][description]" class="rounded border border-slate-300 px-2 py-2"></td><td class="p-2"><input name="lines['+i+'][statement_amount]" inputmode="decimal" required class="w-32 rounded border border-slate-300 px-2 py-2"></td><td class="p-2"><button type="button" data-remove-line class="text-rose-700">Remove</button></td>';tbody.appendChild(row);bind(row);});
})();
</script>
